20	/**
21	 * The data type representing {@code string} type values.
22	 *
23	 * @since 3.0.0
24	 */
25	@Evolving
26	public class StringType extends BasePrimitiveType {
27	  public static final StringType STRING = new StringType(CollationIdentifier.SPARK_UTF8_BINARY);
28	
29	  private final CollationIdentifier collationIdentifier;
30	
31	  /**
32	   * @param collationIdentifier An identifier representing the collation to be used for string
33	   *     comparison and sorting. This determines how strings will be ordered and compared in query
34	   *     operations.
35	   */
36	  public StringType(CollationIdentifier collationIdentifier) {
37	    super("string");
38	    this.collationIdentifier = collationIdentifier;
39	  }
40	
41	  /**
42	   * @param collationName name of collation in which this StringType will be observed. In form of
43	   *     {@code PROVIDER.COLLATION_NAME[.VERSION]}
44	   */
45	  public StringType(String collationName) {
46	    super("string");
47	    this.collationIdentifier = CollationIdentifier.fromString(collationName);
48	  }
49	
50	  /** @return StringType's collation identifier */
51	  public CollationIdentifier getCollationIdentifier() {
52	    return collationIdentifier;
53	  }
54	
55	  /**
56	   * Are the data types same? The metadata, collations or column names could be different.
57	   *
58	   * @param dataType
59	   * @return
60	   */
61	  public boolean equivalent(DataType dataType) {
62	    return dataType instanceof StringType;
63	  }
64	
65	  /**
66	   * Checks whether the given {@code dataType} is compatible with this type when writing data.
67	   * Collation differences are ignored.
68	   *
69	   * <p>This method is intended to be used during the write path to validate that an input type
70	   * matches the expected schema before data is written.
71	   *
72	   * <p>It should not be used in other cases, such as the read path.
73	   *
74	   * @param dataType the input data type being written
75	   * @return {@code true} if the input type is compatible with this type.
76	   */
77	  @Override
78	  public boolean isWriteCompatible(DataType dataType) {
79	    return dataType instanceof StringType;
80	  }
81	
82	  /** @return true if this StringType uses the default Spark UTF8_BINARY collation. */
83	  public boolean isUTF8BinaryCollated() {
84	    return collationIdentifier.isSparkUTF8BinaryCollation();
85	  }
86	
87	  @Override
88	  public boolean equals(Object o) {
89	    if (!(o instanceof StringType)) {
90	      return false;
91	    }
92	
93	    StringType that = (StringType) o;
94	    return collationIdentifier.equals(that.collationIdentifier);
95	  }
96	
97	  /**
98	   * Override is needed because {@code toString()} may be used for schema serialization and similar
99	   * contexts, so collation information must be included.
100	   *
101	   * @return string representation of the StringType.
102	   */
103	  @Override
104	  public String toString() {
105	    if (isUTF8BinaryCollated()) {
106	      return super.toString();
107	    } else {
108	      return String.format("string collate %s", collationIdentifier.getName());
109	    }
110	  }
111	}
