72	    if (this == o) {
73	      return true;
74	    }
75	    if (o == null || getClass() != o.getClass()) {
76	      return false;
77	    }
78	    DecimalType that = (DecimalType) o;
79	    return precision == that.precision && scale == that.scale;
80	  }
81	
