package io.delta.kernel.types;

import io.delta.kernel.annotation.Evolving;
import java.util.Objects;

/**
 * The data type representing {@code geometry} type values, i.e. planar (cartesian) spatial data. A
 * geometry type is parameterized by a Spatial Reference System Identifier (SRID) in {@code
 * authority:code} notation (e.g. {@code OGC:CRS84}, {@code EPSG:4326}).
 *
 * <p>Two {@link GeometryType} instances are equal if and only if they have the same SRID. SRID
 * matching is case-sensitive.
 *
 * @since 3.0.0
 */
@Evolving
public final class GeometryType extends DataType {

  /** The default SRID used when none is specified. */
  public static final String DEFAULT_SRID = "OGC:CRS84";

  /** @return a {@link GeometryType} with the default SRID {@code OGC:CRS84}. */
  public static GeometryType ofDefault() {
    return new GeometryType(DEFAULT_SRID);
  }

  /**
   * @param srid the Spatial Reference System Identifier in {@code authority:code} notation.
   * @return a {@link GeometryType} with the given SRID.
   */
  public static GeometryType ofSRID(String srid) {
    return new GeometryType(srid);
  }

  private final String srid;

  private GeometryType(String srid) {
    this.srid = srid;
  }

  /** @return the Spatial Reference System Identifier of this geometry type. */
  public String getSrid() {
    return srid;
  }

  @Override
  public boolean isNested() {
    return false;
  }

  @Override
  public String toString() {
    return String.format("Geometry(srid=%s)", srid);
  }

  @Override
  public boolean equals(Object o) {
    if (this == o) {
      return true;
    }
    if (o == null || getClass() != o.getClass()) {
      return false;
    }
    GeometryType that = (GeometryType) o;
    return Objects.equals(srid, that.srid);
  }

  @Override
  public int hashCode() {
    return Objects.hash(srid);
  }
}
